use vstd::prelude::*;

verus! {

fn ones_like<T>(a: &Vec<T>) -> (result: Vec<i32>)
    ensures
        // The output has the same length as the input
        result.len() == a.len(),
    ensures
        // Every element of the output is 1
        forall |i: usize| i < result.len() ==> result[i] == 1
{
    let mut result: Vec<i32> = Vec::new();
    let n: usize = a.len();
    let mut i: usize = 0;
    // Loop to build `result` one element at a time
    while i < n
        invariant
            // The loop counter stays within [0, n]
            i <= n,
        invariant
            // We've written exactly `i` elements so far
            result.len() == i,
        invariant
            // All written elements are 1
            forall |j: usize| j < result.len() ==> result[j] == 1,
        decreases
            // We make progress by decreasing the number of remaining iterations
            n - i
    {
        result.push(1);
        i += 1;
    }
    result
}

}

